input.sparql:
SELECT ?point ?tid WHERE {
  ?z a brick:Zone ; brick:hasName "Perimeter_bot_ZN_3" .
  ?point brick:isPartOf ?z ; brick:hasPropertyType brick:Air_Temperature .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tid .
}

SELECT ?z WHERE {
  ?z a brick:Zone .
  FILTER (str(?z) LIKE "%Perimeter_bot_ZN_3%")
}

SELECT ?z ?name WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name .
  FILTER (CONTAINS(str(?name), "Perimeter_bot_ZN_3"))
}
